CREATE TABLE IF NOT EXISTS platform_maintenance (id BOOLEAN PRIMARY KEY DEFAULT TRUE CHECK (id), status VARCHAR(10) NOT NULL DEFAULT 'OFF' CHECK (status IN ('OFF','PARTIAL','FULL')), message TEXT NOT NULL DEFAULT '', starts_at TIMESTAMPTZ, ends_at TIMESTAMPTZ, affected_clients TEXT[] NOT NULL DEFAULT '{}', reason TEXT NOT NULL DEFAULT '', updated_by UUID REFERENCES admin_users(id), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
INSERT INTO platform_maintenance (id) VALUES (TRUE) ON CONFLICT (id) DO NOTHING;
CREATE TABLE IF NOT EXISTS admin_announcements (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), title VARCHAR(180) NOT NULL, message TEXT NOT NULL, audience VARCHAR(30) NOT NULL CHECK (audience IN ('ALL','BUYERS','SELLERS','EMPLOYEES','ADMINS')), status VARCHAR(20) NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','SCHEDULED','ACTIVE','EXPIRED','ARCHIVED')), starts_at TIMESTAMPTZ, ends_at TIMESTAMPTZ, created_by UUID NOT NULL REFERENCES admin_users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_admin_announcements_active ON admin_announcements(status, starts_at, ends_at);
CREATE TABLE IF NOT EXISTS admin_approval_requests (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), action_type VARCHAR(80) NOT NULL, requested_by UUID NOT NULL REFERENCES admin_users(id), target_type VARCHAR(80) NOT NULL, target_id TEXT NOT NULL DEFAULT '', payload JSONB NOT NULL DEFAULT '{}', reason TEXT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','APPROVED','REJECTED','CANCELLED')), resolved_by UUID REFERENCES admin_users(id), resolution_reason TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), resolved_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS idx_admin_approvals_status ON admin_approval_requests(status, created_at DESC);
CREATE TABLE IF NOT EXISTS admin_export_jobs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), dataset VARCHAR(40) NOT NULL, filters JSONB NOT NULL DEFAULT '{}', status VARCHAR(20) NOT NULL DEFAULT 'QUEUED' CHECK (status IN ('QUEUED','RUNNING','COMPLETED','FAILED')), requested_by UUID NOT NULL REFERENCES admin_users(id), file_path TEXT, error_message TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), completed_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS idx_admin_export_jobs_requester ON admin_export_jobs(requested_by, created_at DESC);
